  <label class="setting-field">\u041A\u043E\u043C\u043D\u0430\u0442\u0430 / \u0437\u043E\u043D\u0430<select id="catalog-room">${Rt.map(t=>`<option value="${t.id}" ${e.room===t.id?"selected":""}>${t.name}</option>`).join("")}</select></label>
